def body(x,y,a,clearance=0):
 f=FRONT+clearance;r=REAR+clearance;w=VEH['width_m']/2+clearance;c=math.cos(a);s=math.sin(a)
 return Polygon([(x+c*u-s*v,y+s*u+c*v) for u,v in [(f,w),(f,-w),(-r,-w),(-r,w)]])
def sample_straight(p,h,d,step=.12):
 return [(p[0]+math.cos(h)*t,p[1]+math.sin(h)*t,h) for t in np.linspace(0,d,max(2,int(abs(d)/step)+1))]
def arc(start,h0,delta,R):
 sg=1 if delta>0 else -1;vals=np.linspace(0,delta,max(3,int(abs(delta)*R/VEH['sample_step_m'])+1));x,y=start
 return [(x+sg*R*(math.sin(h0+t)-math.sin(h0)),y+sg*R*(-math.cos(h0+t)+math.cos(h0)),h0+t) for t in vals]
def test(poses,pavement,obstacles):
 for x,y,a in poses:
  p=body(x,y,a,VEH['clearance_m'])
  if not pavement.covers(p):return False,'pavement_boundary'
  if obstacles is not None and p.intersects(obstacles):return False,'occupied_neighbor'
 return True,'pass'
def fit_bank(spec):
 sx=22*FT/(spec['drive_right']-spec['drive_left']);sy=22*FT/(spec['south_far']-spec['bank_bottom']);back=spec['bank_back'];right=spec['drive_left'];top=spec['bank_top'];bottom=spec['bank_bottom'];rad=spec['cap_radius'];cx=right-rad
 pts=[(back-3,top),(cx,top)]
 pts += [(cx+rad*math.cos(a),top+rad+rad*math.sin(a)) for a in np.linspace(-math.pi/2,0,32)]
 pts += [(right,bottom-rad)]
 pts += [(cx+rad*math.cos(a),bottom-rad+rad*math.sin(a)) for a in np.linspace(0,math.pi/2,32)]
 pts += [(back-3,bottom)]
 mask=Polygon(pts)
 def metric(g):return affinity.scale(affinity.translate(g,xoff=-back,yoff=-top),xfact=sx,yfact=sy,origin=(0,0))
 height=7*SW/sy;desired=(top+bottom-height)/2;possible=[]
 # Keep the original rear bank line. Fit count and dimensions rather than shrinking bays.
 for y0 in np.arange(top+1,bottom-height-1,.25):
  bank=box(back,y0,back+L/sx,y0+height)
  if mask.buffer(-1).covers(bank):possible.append((abs(y0-desired),float(y0),bank))
 if not possible:return {'fit':False,'local_m_per_pixel':[sx,sy],'available_envelope_length_ft':(bottom-top)*sy/FT,'required_bank_length_ft':63,'source_work_mask':mapping(mask)},None
 _,y0,bank=min(possible,key=lambda x:x[0]);end=y0+height
 bays=[box(back,y0+k*SW/sy,back+L/sx,y0+(k+1)*SW/sy) for k in range(7)]
 proposed=box(back,y0,right+2,end).intersection(mask.buffer(.0001));proposed=proposed.union(bank)
 # The existing road is to the east of the curved bank, plus the unchanged north/south connecting aisles.
 source_drive=box(right,top-210,spec['drive_right'],spec['south_far'])
 source_drive=source_drive.union(box(back-70,top-58,spec['drive_right'],top)).union(box(back-70,bottom,spec['drive_right']+120,spec['south_far']))
 source_drive=source_drive.union(box(back-3,top,right,bottom).difference(mask))
 initial_pavement=metric(source_drive.union(proposed));pavement=metric(source_drive.union(mask));prepare(pavement)
 return {'fit':True,'scale_basis':'22-foot clear east aisle and 22-foot clear south connecting aisle, separately calibrated axes','local_m_per_pixel':[sx,sy],'pixel_trace_uncertainty_px':2,'scale_field_verified':False,'required_bank_length_ft':63,'available_envelope_length_ft':(bottom-top)*sy/FT,'bay_pixel_origin':[back,y0],'source_work_mask':mapping(mask),'initial_pavement_metric':mapping(initial_pavement),'new_pavement_pixels':mapping(proposed),'new_bays_pixels':[mapping(g) for g in bays],'pavement_metric':mapping(pavement),'source_drive_metric':mapping(metric(source_drive))},(metric,pavement,metric(source_drive),[metric(g) for g in bays])

def bank_paths(data):
 metric,paved,source_drive,bays=data;results=[]
 # Correct right-hand travel lane for southbound vehicles approaching the bank.
 aisle_left=source_drive.bounds[0]  # Use the actual straight eastern corridor below instead of the junction flare.
 source_bounds=[g.bounds for g in getattr(source_drive,'geoms',[source_drive])]
 # The 22-ft east aisle's right edge is invariant in the source straight segment.
 sample_y=bays[3].centroid.y
 section=source_drive.intersection(LineString([(-10,sample_y),(40,sample_y)]))
 left,right=section.bounds[0],section.bounds[2];proper_x=left+(right-left)/4
 for k,bay in enumerate(bays):
  c=bay.centroid;goal=(c.x+CG,c.y);cars=unary_union([body(g.centroid.x+CG,g.centroid.y,math.pi) for j,g in enumerate(bays) if j!=k]);prepare(cars);found=None;failures={};attempts=0
  # A smooth, bounded-curvature lateral setup starts in the proper southbound lane.
  # Using the opposing half during a parking maneuver requires yielding; it is not an unexplained start there.
  for R in [4.,4.25,4.5,4.75,5.,5.5,6.]:
   if R<MIN_R:continue
   if found:break
   for d in [0,.5,1.,1.5,2.,2.5,3.,3.25,3.5,3.75,4.,4.5,5.]:
    if found:break
    h0=math.pi/2;delta=math.pi/2;hg=math.pi;Q=(goal[0]+d,goal[1]);S=(Q[0]+R,Q[1]-R);shift=S[0]-proper_x
    for run in [8.,10.,12.,14.,16.,18.]:
     attempts+=1;setup_kappa=6*abs(shift)/run**2
     if setup_kappa>1/MIN_R:continue
     ts=np.linspace(0,1,max(3,int(math.hypot(run,shift)/.08)+1));setup=[]
     for t in ts:
      x=proper_x+shift*(3*t*t-2*t*t*t);y=S[1]-run+run*t;dx=shift*(6*t-6*t*t);heading=math.atan2(run,dx);setup.append((float(x),float(y),heading))
     if not source_drive.covers(body(*setup[0],.15)):failures['initial_aisle_position']=failures.get('initial_aisle_position',0)+1;continue
     first=body(*setup[0],.15)
     if first.bounds[2]>(left+right)/2+.0001:failures['wrong_initial_lane']=failures.get('wrong_initial_lane',0)+1;continue
     poses=setup+arc(S,h0,delta,R)[1:]+sample_straight(Q,hg,d)[1:];ok,why=test(poses,paved,cars)
     if not ok:failures[why]=failures.get(why,0)+1;continue
     swept=unary_union([body(*p) for p in poses]);minimum=float(swept.distance(paved.boundary));neighbor=float(swept.distance(cars));found={'passed':True,'stall':k+1,'entry':'Forward from proper southbound lane, bounded-curvature lateral setup while yielding, turn, then straight into bay','exit':'Reverse the checked trajectory to the original proper lane; then proceed forward along the retained aisle','uses_opposing_half_during_maneuver':True,'requires_yielding_to_other_traffic':True,'starts_in_proper_travel_lane':True,'rear_axle_turn_radius_m':float(R),'setup_min_radius_m':None if setup_kappa<1e-8 else 1/setup_kappa,'steering_angle_deg':math.degrees(math.atan(VEH['wheelbase_m']*max(setup_kappa,1/R))),'final_straight_m':d,'setup_length_m':run,'minimum_boundary_clearance_m':minimum,'minimum_neighbor_clearance_m':neighbor,'sample_count':len(poses),'poses':poses,'swept_envelope_metric':mapping(swept),'attempts':attempts};break
  results.append(found or {'passed':False,'stall':k+1,'attempts':attempts,'failures':failures,'interpretation':'No passing tested lane-correct setup and single-turn maneuver. This is not proof that every multipoint path is impossible.'});print('BAY',k+1,'PASS' if found else 'NO PASS',flush=True)
 return results

def approach(spec):
 # Local affine calibration: 16-ft west leg / 22-ft north cross aisle. No whole-plan scale is asserted.
 sx=16*FT/(spec['west_right']-spec['west_left']);sy=22*FT/(spec['north_bottom']-spec['north_top']);ox=spec['west_left'];oy=spec['north_top']
 def metric(g):return affinity.scale(affinity.translate(g,xoff=-ox,yoff=-oy),xfact=sx,yfact=sy,origin=(0,0))
 c=spec['west_center'];straight=unary_union([box(spec['west_left'],oy,spec['west_right'],oy+260),box(c,oy,c+300,spec['north_bottom'])]);paved=metric(straight);prepare(paved);found=None
 for R in np.arange(math.ceil(MIN_R*10)/10,6.51,.25):
  for endx in np.arange(1.7,3.21,.15):
   for sy0 in np.arange(1.3,4.51,.2):
    S=(endx+R,sy0);P=(S[0]+8,S[1]);turn=arc(S,math.pi,-math.pi/2,R);E=turn[-1];poses=sample_straight(P,math.pi,8)+turn[1:]+sample_straight((E[0],E[1]),math.pi/2,8)[1:];ok,why=test(poses,paved,None)
    if ok:
     swept=unary_union([body(*p) for p in poses]);found={'passed':True,'direction':'west along north cross aisle, then south into straight 16-ft west leg','rear_axle_turn_radius_m':float(R),'minimum_boundary_clearance_m':float(swept.distance(paved.boundary)),'poses':poses,'swept_envelope_metric':mapping(swept),'straight_pavement_pixels':mapping(straight),'local_m_per_pixel':[sx,sy],'scale_field_verified':False};break
   if found:break
  if found:break
 return found or {'passed':False,'reason':'No passing tested one-arc turn in the proposed straight T geometry.'}

if __name__=='__main__':
 summary={'source':'parking_options_1-3.pdf','source_pdf_sha256':hashlib.sha256((W/'source.pdf').read_bytes()).hexdigest(),'vehicle':VEH,'minimum_rear_axle_radius_m':MIN_R,'initial_lane_rule':'Right-hand travel; southbound starts in the bank-side half of the existing 22-foot east aisle. Parking setup may use the opposing half while yielding.','scope':'Seven proposed annex bays and the straight northwest approach only. Existing locked parking banks elsewhere are not certified. Local raster calibration uses owner dimensions; source PDF has no measured scale.','limitations':['Low-speed planar kinematic bicycle model','Steering may change while stopped; steering rate and road grades not simulated','Manual raster curb traces have approximately +/-2 pixel uncertainty','Forward ingress and reverse egress checked with the other six bays occupied','A failed search is not proof that no multipoint path exists','No revised graphic is generated before reviewing these checks'],'options':{}}
 for i,spec in SPECS.items():
  print('OPTION',i,flush=True);fit,data=fit_bank(spec);r={'source_features_pixels':spec,'bank_fit':fit};r['annex_turning']=bank_paths(data) if data else [];
